export function createRetryCache({ loader, ttlMs, now }) {
  const entries = new Map();

  return {
    get(key, options = {}) {
            const existing = entries.get(key);
            if (existing && (existing.pending || now() < existing.expiresAt)) {
                return existing.promise;
            }

            let resolve, reject;
            const promise = new Promise((res, rej) => {
                resolve = res;
                reject = rej;
            });

            entries.set(key, { promise, pending: true });

            Promise.resolve()
                .then(() => loader(key, options))
                .then(value => {
                    entries.set(key, { promise, expiresAt: now() + ttlMs });
                    resolve(value);
                })
                .catch(err => {
                    entries.delete(key);
                    reject(err);
                });

            return promise;
    },
  };
}
